-- ----------------------------------------------------------------------------
-- Users: Application users. Therapists, supervisors, and clients log in via dev-login by user id (email).
-- ----------------------------------------------------------------------------
CREATE TABLE users (
  users_id                            TEXT                 PRIMARY KEY,         -- PK: the user's email.
  full_name                           TEXT                ,
  role                                TEXT                                      -- therapist | supervisor | client
);
COMMENT ON TABLE users IS 'Application users. Therapists, supervisors, and clients log in via dev-login by user id (email).';
COMMENT ON COLUMN users.users_id IS 'PK: the user''s email.';
COMMENT ON COLUMN users.role IS 'therapist | supervisor | client';

-- ----------------------------------------------------------------------------
-- Clients: People in treatment. Each has an assigned therapist, a set of goals, and a stream of sessions.
-- ----------------------------------------------------------------------------
CREATE TABLE clients (
  clients_id                          TEXT                 PRIMARY KEY,         -- PK: short slug.
  client_name                         TEXT                ,
  therapist                           TEXT                ,                     -- FK to Users.UsersId.
  start_date                          DATE                
);
COMMENT ON TABLE clients IS 'People in treatment. Each has an assigned therapist, a set of goals, and a stream of sessions.';
COMMENT ON COLUMN clients.clients_id IS 'PK: short slug.';
COMMENT ON COLUMN clients.therapist IS 'FK to Users.UsersId.';

-- ----------------------------------------------------------------------------
-- Goals: Treatment goals owned by a client. TargetScore is editable.
-- ----------------------------------------------------------------------------
CREATE TABLE goals (
  goals_id                            TEXT                 PRIMARY KEY,
  title                               TEXT                ,
  client                              TEXT                ,
  target_score                        NUMERIC                                   -- 0-10. EDITABLE.
);
COMMENT ON TABLE goals IS 'Treatment goals owned by a client. TargetScore is editable.';
COMMENT ON COLUMN goals.target_score IS '0-10. EDITABLE.';

-- ----------------------------------------------------------------------------
-- Sessions: Therapy sessions. MoodRating is editable and feeds the client-level rollup.
-- ----------------------------------------------------------------------------
CREATE TABLE sessions (
  sessions_id                         TEXT                 PRIMARY KEY,
  client                              TEXT                ,
  session_label                       DATE                ,
  duration_minutes                    INTEGER             ,
  mood_rating                         INTEGER             ,                     -- 1-10. EDITABLE.
  notes                               TEXT                
);
COMMENT ON TABLE sessions IS 'Therapy sessions. MoodRating is editable and feeds the client-level rollup.';
COMMENT ON COLUMN sessions.mood_rating IS '1-10. EDITABLE.';

-- ----------------------------------------------------------------------------
-- GoalUpdates: Per-session goal progress entries. ScoreAchieved is editable.
-- ----------------------------------------------------------------------------
CREATE TABLE goal_updates (
  goal_updates_id                     TEXT                 PRIMARY KEY,
  goal                                TEXT                ,
  "session"                           TEXT                ,
  score_achieved                      NUMERIC                                   -- 0-10. EDITABLE.
);
COMMENT ON TABLE goal_updates IS 'Per-session goal progress entries. ScoreAchieved is editable.';
COMMENT ON COLUMN goal_updates.score_achieved IS '0-10. EDITABLE.';

-- ============================================================================
-- FK INDEXES - Performance only, always applied
-- ============================================================================

-- Clients
CREATE INDEX IF NOT EXISTS idx_clients_therapist ON clients (therapist);

-- Goals
CREATE INDEX IF NOT EXISTS idx_goals_client ON goals (client);

-- Sessions
CREATE INDEX IF NOT EXISTS idx_sessions_client ON sessions (client);

-- GoalUpdates
CREATE INDEX IF NOT EXISTS idx_goal_updates_goal ON goal_updates (goal);
CREATE INDEX IF NOT EXISTS idx_goal_updates_session ON goal_updates ("session");

